Tool response:
Tool: submit_code_review
Description: Submit Code Review
Parameters:
    {
      "type": "object",
      "properties": {
        "assignment_title": {
          "type": "string",
          "description": "Title of the assignment to submit code review for",
          "title": "Assignment Title"
        },
        "course_code": {
          "type": "string",
          "description": "Course code where the assignment belongs",
          "title": "Course Code"
        },
        "repository_url": {
          "type": "string",
          "description": "URL of the Git repository containing the code",
          "title": "Repository Url"
        },
        "branch": {
          "type": "string",
          "description": "Branch name in the repository (defaults to 'main')",
          "default": "main",
          "title": "Branch"
        }
      },
      "required": [
        "assignment_title",
        "course_code",
        "repository_url"
      ]
    }

